-- 10 artikel berita pertama (keputusan owner, 20 November 2026): berita properti terbaru yang relevan
-- bagi calon pembeli, ditulis sendiri dari sumber yang tercantum di blok "sources" tiap artikel.
-- Sampul foto stok Unsplash (kredit di docs/brand.md). UUID tetap supaya prerender CI dan production sama.

insert into public.posts (id, slug, title, excerpt, body, cover_path, cover_alt, content_status, published_at)
values (
  '5a7e0000-0000-4000-8000-000000000601',
  'bi-rate-naik-ke-6-persen-cara-menjaga-cicilan-kpr',
  $t$BI-Rate naik ke 6 persen: cara menjaga cicilan KPR tetap terkendali$t$,
  $e$Bank Indonesia menaikkan BI-Rate 25 basis poin pada 18 November 2026. Ini yang perlu dicek calon pembeli rumah sebelum memilih skema bunga KPR.$e$,
  $body$[{"type": "paragraph", "text": "Rapat Dewan Gubernur Bank Indonesia pada 17 dan 18 November 2026 memutuskan BI-Rate naik 25 basis poin menjadi 6,00 persen. Suku bunga Deposit Facility menjadi 5,25 persen dan Lending Facility menjadi 6,75 persen."}, {"type": "paragraph", "text": "Menurut siaran pers BI, kenaikan ini dilakukan untuk menjaga stabilitas rupiah di tengah ketidakpastian global, sekaligus langkah antisipasi supaya inflasi 2026 dan 2027 tetap di sasaran 2,5 persen plus minus 1 persen. Di sisi lain, ekonomi Indonesia tumbuh 5,47 persen pada triwulan III 2026, lebih tinggi dari 5,29 persen pada triwulan sebelumnya."}, {"type": "heading", "text": "Siapa yang terdampak"}, {"type": "paragraph", "text": "Dampaknya berbeda untuk setiap skema KPR. Kuncinya ada di jenis bunga yang Anda pakai."}, {"type": "list", "items": ["KPR bunga mengambang (floating): cicilan bisa ikut naik saat bank menyesuaikan suku bunganya. Penyesuaian biasanya tidak langsung, tergantung kebijakan masing-masing bank.", "KPR yang masih dalam masa bunga tetap (fixed): cicilan tidak berubah sampai masa fixed selesai.", "KPR subsidi FLPP: bunganya tetap 5 persen sepanjang tenor dan tidak mengikuti BI-Rate.", "KPR syariah dengan akad murabahah: angsuran sudah dikunci sejak akad, sehingga tidak berubah."]}, {"type": "heading", "text": "Lima langkah sebelum tanda tangan akad"}, {"type": "list", "items": ["Tanyakan berapa lama masa bunga fixed dan berapa perkiraan bunga floating setelahnya.", "Hitung cicilan dengan dua angka: bunga promo dan bunga floating. Pastikan cicilan tetap aman di angka yang lebih tinggi.", "Jaga total cicilan di kisaran sepertiga penghasilan bulanan. Banyak bank memakai patokan ini saat menilai pengajuan.", "Pertimbangkan uang muka yang lebih besar supaya pokok pinjaman dan bunganya lebih kecil.", "Bandingkan beberapa bank, termasuk produk syariah yang angsurannya tetap."]}, {"type": "paragraph", "text": "Kenaikan BI-Rate bukan alasan untuk menunda rencana, tapi alasan untuk menghitung lebih teliti. Coba Simulasi KPR di website ini: masukkan bunga fixed, lalu bunga floating, dan lihat perbedaan cicilannya dalam hitungan detik."}, {"type": "sources", "items": [{"label": "Bank Indonesia, siaran pers 18 November 2026: BI-Rate naik 25 bps menjadi 6,00%", "url": "https://www.bi.go.id/id/publikasi/ruang-media/news-release/Pages/sp_2825426.aspx"}, {"label": "Bisnis.com, 10 Juni 2026: bunga KPR subsidi tetap 5%", "url": "https://ekonomi.bisnis.com/read/20260610/47/1979833/bi-rate-naik-maruarar-pastikan-bunga-kpr-subsidi-tetap-5"}]}]$body$::jsonb,
  '/images/berita/bi-rate-cicilan-kpr.webp',
  $a$Foto ilustrasi kalkulator dan lembar perhitungan di meja kerja$a$,
  'terbit',
  '2026-11-20T10:00:00Z'
) on conflict do nothing;

insert into public.posts (id, slug, title, excerpt, body, cover_path, cover_alt, content_status, published_at)
values (
  '5a7e0000-0000-4000-8000-000000000602',
  'kpr-flpp-2026-kuota-350-ribu-unit-tenor-40-tahun',
  $t$KPR FLPP 2026: kuota 350 ribu unit dan tenor hingga 40 tahun$t$,
  $e$Penyaluran KPR subsidi FLPP mencapai 160.070 unit sampai September 2026. BP Tapera menyasar ASN, pekerja swasta, dan buruh untuk sisa tahun ini.$e$,
  $body$[{"type": "paragraph", "text": "BP Tapera mencatat penyaluran FLPP sebanyak 160.070 unit sampai September 2026, atau 45,73 persen dari target tahun ini. Hampir semuanya rumah tapak, yaitu 160.053 unit. Sisanya 17 unit rumah susun."}, {"type": "paragraph", "text": "Target FLPP 2026 adalah 350.000 unit. Pada awal November, realisasinya dilaporkan sudah mencapai 57,34 persen."}, {"type": "heading", "text": "Masih ada potensi 48.679 unit"}, {"type": "paragraph", "text": "Komisioner BP Tapera Heru Pudyo Nugroho menyebut masih ada potensi permintaan 48.679 unit untuk tiga bulan terakhir 2026. Angka ini berasal dari data pengembang yang terdaftar di sistem BP Tapera: kavling, rumah yang sudah dipesan, dan rumah siap huni. Kalau semuanya terealisasi, total FLPP tahun ini bisa mencapai 208.749 unit."}, {"type": "paragraph", "text": "Untuk mengejar sisa kuota, BP Tapera menyasar calon debitur berpenghasilan tetap: aparatur sipil negara, pekerja swasta, dan buruh. Kerja sama dengan bagian HRD perusahaan juga dibuka untuk sosialisasi langsung ke karyawan."}, {"type": "heading", "text": "Tenor sampai 40 tahun"}, {"type": "paragraph", "text": "Pemerintah memberi opsi tenor cicilan FLPP hingga 40 tahun bagi masyarakat berpenghasilan rendah. Tenor yang lebih panjang membuat cicilan bulanan lebih kecil, sehingga rumah pertama lebih terjangkau."}, {"type": "heading", "text": "Yang perlu disiapkan"}, {"type": "list", "items": ["Pastikan penghasilan masuk batas masyarakat berpenghasilan rendah sesuai ketentuan pemerintah dan belum memiliki rumah.", "Siapkan KTP, kartu keluarga, NPWP, dan bukti penghasilan.", "Pilih rumah dari pengembang yang terdaftar di sistem pemerintah dan bank penyalur FLPP."]}, {"type": "paragraph", "text": "Tidak semua rumah masuk skema FLPP. Rumah di Sejahtera Green Village dibeli lewat KPR komersial atau KPR syariah. Marketing kami bisa membantu membandingkan skema yang paling sesuai dengan penghasilan Anda."}, {"type": "sources", "items": [{"label": "Katadata, 29 September 2026: penyaluran FLPP 45,73%, BP Tapera kejar tambahan 48.679 unit", "url": "https://katadata.co.id/berita/industri/6abb58d87b3ce/penyaluran-flpp-baru-45-73-bp-tapera-kejar-tambahan-48679-unit-di-akhir-2026"}, {"label": "Bisnis.com, 6 November 2026: realisasi KPR FLPP 57,34%", "url": "https://ekonomi.bisnis.com/read/20261106/47/2019114/sisa-2-bulan-realisasi-kpr-flpp-baru-5734"}]}]$body$::jsonb,
  '/images/berita/kpr-flpp-2026.webp',
  $a$Foto ilustrasi tangan memegang kunci di atas maket rumah$a$,
  'terbit',
  '2026-11-20T09:00:00Z'
) on conflict do nothing;

insert into public.posts (id, slug, title, excerpt, body, cover_path, cover_alt, content_status, published_at)
values (
  '5a7e0000-0000-4000-8000-000000000603',
  'program-3-juta-rumah-capai-1-79-juta-unit',
  $t$Program 3 juta rumah capai 1,79 juta unit hingga Oktober 2026$t$,
  $e$Kementerian PKP mencatat 1,79 juta unit rumah baru dan renovasi sejak Januari 2025. Ini rinciannya dan artinya bagi pencari rumah.$e$,
  $body$[{"type": "paragraph", "text": "Kementerian Perumahan dan Kawasan Permukiman (PKP) mencatat capaian kumulatif program perumahan sebesar 1.790.081 unit sejak Januari 2025 sampai 15 Oktober 2026. Angka ini terdiri dari sekitar 1,1 juta rumah baru dan 686.163 unit renovasi rumah tidak layak huni."}, {"type": "paragraph", "text": "Angka tersebut menggabungkan pembangunan yang dibiayai APBN dan yang dikerjakan di luar APBN, termasuk oleh pengembang swasta dan masyarakat secara swadaya."}, {"type": "heading", "text": "Dua angka yang sering tertukar"}, {"type": "paragraph", "text": "Pada pertengahan Juni 2026, realisasi program dilaporkan 324.213 unit. Angka itu adalah capaian tahun berjalan pada periode tersebut, sedangkan 1,79 juta unit adalah angka kumulatif sejak 2025. Keduanya benar, hanya mengukur periode yang berbeda."}, {"type": "heading", "text": "Apa artinya bagi pencari rumah"}, {"type": "list", "items": ["Pasokan rumah baru bertambah di banyak daerah, sehingga pilihan lokasi dan harga makin beragam.", "Program pembiayaan seperti KPR subsidi, insentif PPN, dan kredit program perumahan berjalan bersamaan.", "DPR meminta program ini tepat sasaran untuk masyarakat berpenghasilan rendah, sehingga verifikasi calon penerima semakin ketat. Siapkan dokumen dengan lengkap sejak awal."]}, {"type": "paragraph", "text": "Lebih banyak pilihan berarti calon pembeli perlu lebih teliti membandingkan. Cek legalitas, akses, dan rincian biaya setiap proyek sebelum memutuskan."}, {"type": "sources", "items": [{"label": "Bisnis.com, 28 Oktober 2026: Fraksi PKB desak program 3 juta rumah tepat sasaran", "url": "https://ekonomi.bisnis.com/read/20261028/47/2016293/fraksi-pkb-desak-program-3-juta-rumah-tepat-sasaran"}, {"label": "Antara, Juni 2026: realisasi program 3 juta rumah capai 324.213 unit", "url": "https://www.antaranews.com/berita/5610987/realisasi-program-3-juta-rumah-capai-324213-unit-hingga-juni-2026"}]}]$body$::jsonb,
  '/images/berita/program-3-juta-rumah.webp',
  $a$Foto ilustrasi pekerja konstruksi berhelm di lokasi pekerjaan$a$,
  'terbit',
  '2026-11-20T08:00:00Z'
) on conflict do nothing;

insert into public.posts (id, slug, title, excerpt, body, cover_path, cover_alt, content_status, published_at)
values (
  '5a7e0000-0000-4000-8000-000000000604',
  'kredit-properti-tumbuh-16-persen-september-2026',
  $t$Kredit properti tumbuh 16,4 persen per September 2026$t$,
  $e$Penyaluran kredit properti mencapai Rp1.703,7 triliun. KPR dan KPA tumbuh 4,3 persen menjadi Rp863,1 triliun.$e$,
  $body$[{"type": "paragraph", "text": "Data Bank Indonesia menunjukkan kredit properti tumbuh 16,4 persen secara tahunan menjadi Rp1.703,7 triliun pada September 2026. Pertumbuhannya sedikit melambat dibanding Agustus 2026 yang mencapai 18,3 persen."}, {"type": "paragraph", "text": "Khusus kredit pemilikan rumah dan apartemen (KPR dan KPA), penyaluran tumbuh 4,3 persen menjadi Rp863,1 triliun. Angka ini sedikit naik dari pertumbuhan 4,2 persen pada Agustus."}, {"type": "heading", "text": "Kredit program perumahan ikut berjalan"}, {"type": "paragraph", "text": "Selain KPR, pemerintah dan perbankan juga menyalurkan kredit program perumahan untuk pelaku usaha di sektor ini. Realisasinya dilaporkan mencapai Rp29,1 triliun per 31 Oktober 2026."}, {"type": "heading", "text": "Yang bisa dimanfaatkan calon pembeli"}, {"type": "list", "items": ["Bank masih aktif menyalurkan KPR. Bandingkan penawaran dari beberapa bank sebelum memilih.", "Tanyakan promo bunga fixed dan berapa lama masa berlakunya.", "Pastikan riwayat kredit di SLIK OJK bersih supaya pengajuan lebih lancar.", "Siapkan dokumen penghasilan yang rapi: slip gaji, rekening koran, atau laporan usaha."]}, {"type": "paragraph", "text": "Pertumbuhan kredit menunjukkan pembiayaan rumah tetap tersedia. Tugas calon pembeli adalah memilih produk yang cicilannya tetap nyaman untuk jangka panjang."}, {"type": "sources", "items": [{"label": "Kontan, Oktober 2026: kredit properti tumbuh 16,4% pada September 2026", "url": "https://keuangan.kontan.co.id/news/kredit-properti-tumbuh-164-pada-september-2026"}, {"label": "IDX Channel: realisasi KUR perumahan capai Rp29,1 triliun", "url": "https://www.idxchannel.com/economics/kementerian-pkp-sebut-realisasi-kur-perumahan-capai-rp291-triliun/all"}]}]$body$::jsonb,
  '/images/berita/kredit-properti-2026.webp',
  $a$Foto ilustrasi gedung tinggi dan kawasan hijau di kota$a$,
  'terbit',
  '2026-11-20T07:00:00Z'
) on conflict do nothing;

insert into public.posts (id, slug, title, excerpt, body, cover_path, cover_alt, content_status, published_at)
values (
  '5a7e0000-0000-4000-8000-000000000605',
  'beli-rumah-baru-bebas-ppn-2026-ini-syarat-lengkapnya',
  $t$Beli rumah baru bebas PPN di 2026: ini syarat lengkapnya$t$,
  $e$PMK 90/2025 menanggung PPN rumah baru sampai harga Rp2 miliar sepanjang 2026. Pemerintah juga menyampaikan rencana perpanjangan hingga akhir 2027.$e$,
  $body$[{"type": "paragraph", "text": "Pembelian rumah baru dari pengembang biasanya dikenai PPN 11 persen. Untuk rumah seharga Rp500 juta, angkanya sekitar Rp55 juta. Sepanjang 2026, pajak ini ditanggung pemerintah lewat insentif PPN DTP."}, {"type": "paragraph", "text": "Dasarnya adalah Peraturan Menteri Keuangan Nomor 90 Tahun 2025. Aturan ini ditandatangani 18 Desember 2025 dan berlaku sejak 1 Januari 2026. Berbeda dengan 2025 yang dibagi dua periode, insentif 2026 diberikan penuh 100 persen dari Januari sampai Desember."}, {"type": "heading", "text": "Syarat rumahnya"}, {"type": "list", "items": ["Harga jual paling tinggi Rp5 miliar. PPN yang ditanggung pemerintah adalah bagian harga sampai Rp2 miliar.", "Rumah tapak atau rumah susun baru dalam kondisi siap huni.", "Punya kode identitas rumah dari aplikasi SIKUMBANG milik pemerintah.", "Diserahkan pertama kali oleh pengembang yang membangunnya dan belum pernah dipindahtangankan.", "Penyerahan terjadi antara 1 Januari dan 31 Desember 2026, ditandai akta jual beli atau PPJB lunas beserta berita acara serah terima."]}, {"type": "heading", "text": "Syarat pembelinya"}, {"type": "list", "items": ["Warga negara Indonesia yang memiliki NPWP atau NIK.", "Satu orang hanya untuk satu unit rumah.", "Pembeli yang sudah memakai insentif serupa pada 2023 sampai 2025 tetap boleh, selama syaratnya terpenuhi."]}, {"type": "heading", "text": "Kapan insentif tidak berlaku"}, {"type": "list", "items": ["Uang muka dibayar sebelum 1 Januari 2026.", "Penyerahan rumah di luar tahun 2026.", "Rumah dijual lagi dalam satu tahun sejak diserahkan.", "Pengembang tidak membuat faktur pajak atau tidak mendaftarkan serah terima di SIKUMBANG."]}, {"type": "heading", "text": "Rencana perpanjangan ke 2027"}, {"type": "paragraph", "text": "Menteri Keuangan Purbaya Yudhi Sadewa menyampaikan insentif ini akan diperpanjang hingga 31 Desember 2027. Ketentuan teknisnya akan mengikuti aturan baru, jadi tanyakan kepada pengembang apakah unit pilihan Anda memenuhi syarat saat akad."}, {"type": "sources", "items": [{"label": "Direktorat Jenderal Pajak, 27 Februari 2026: Beli rumah, diskon PPN 100%", "url": "https://pajak.go.id/en/node/119294"}, {"label": "Bisnis.com, 6 Oktober 2026: diskon PPN DTP 100% diperpanjang hingga 2027", "url": "https://finansial.bisnis.com/read/20261006/90/2010231/diskon-ppn-dtp-100-diperpanjang-hingga-2027-begini-kata-bos-btn"}]}]$body$::jsonb,
  '/images/berita/ppn-dtp-rumah-2026.webp',
  $a$Foto ilustrasi tangan menyerahkan uang kertas seratus ribu rupiah$a$,
  'terbit',
  '2026-11-20T06:00:00Z'
) on conflict do nothing;

insert into public.posts (id, slug, title, excerpt, body, cover_path, cover_alt, content_status, published_at)
values (
  '5a7e0000-0000-4000-8000-000000000606',
  'stasiun-bekasi-ekstensi-mulai-dibangun',
  $t$Stasiun Bekasi Ekstensi mulai dibangun, target selesai 18 bulan$t$,
  $e$Pembangunan stasiun berbasis transit di Bekasi Selatan dimulai 24 Juli 2026. Stasiun ini terhubung sky bridge sekitar 300 meter ke Stasiun Bekasi.$e$,
  $body$[{"type": "paragraph", "text": "Menko Infrastruktur dan Pembangunan Kewilayahan Agus Harimurti Yudhoyono bersama PT Summarecon Agung Tbk memulai pembangunan Stasiun Bekasi Ekstensi pada Jumat, 24 Juli 2026. Lokasinya di kawasan Summarecon, Bekasi Selatan, Kota Bekasi."}, {"type": "paragraph", "text": "Stasiun ini adalah bagian dari kawasan berorientasi transit (TOD). Pembangunannya direncanakan 18 bulan, sehingga kalau sesuai jadwal, stasiun ditargetkan rampung sekitar awal 2028."}, {"type": "heading", "text": "Angka-angka proyeknya"}, {"type": "list", "items": ["Nilai investasi sekitar Rp78 miliar sampai Rp80 miliar.", "Luas lahan 7.038 meter persegi dan luas bangunan 6.733 meter persegi, tiga lantai.", "Sky bridge sekitar 300 meter yang menghubungkan kawasan ke Stasiun Bekasi."]}, {"type": "heading", "text": "Cara kerjanya"}, {"type": "paragraph", "text": "Kereta tetap berhenti di Stasiun Bekasi yang sudah ada. Stasiun Bekasi Ekstensi menjadi pintu masuk tambahan untuk penumpang dari arah barat dan selatan, sedangkan stasiun lama lebih banyak melayani arah utara dan timur. Tujuannya mengurangi penumpukan penumpang."}, {"type": "paragraph", "text": "Setelah TOD rampung, direncanakan ada layanan bus rapid transit yang menghubungkan Summarecon Bekasi, Stasiun Bekasi Ekstensi, dan Stasiun LRT Jabodebek. Tahap berikutnya adalah jalur transportasi massal sepanjang 5 km dari Bekasi utara menuju Stasiun LRT Jabodebek."}, {"type": "heading", "text": "Dampak untuk warga timur Bekasi"}, {"type": "paragraph", "text": "Bagi pengguna KRL lintas Bekasi dan Cikarang, termasuk warga Tambun, akses baru ini menambah pilihan titik naik dan perpindahan moda di Kota Bekasi. Transportasi umum yang makin terhubung biasanya ikut mendorong minat hunian di sepanjang jalurnya."}, {"type": "sources", "items": [{"label": "detikFinance, 24 Juli 2026: Stasiun Bekasi bakal diperluas, dikerjakan dalam 18 bulan", "url": "https://finance.detik.com/infrastruktur/d-8588805/stasiun-bekasi-bakal-diperluas-dikerjakan-dalam-18-bulan"}, {"label": "Antara Megapolitan, 25 Juli 2026: AHY resmikan pembangunan Stasiun Bekasi Ekstensi", "url": "https://megapolitan.antaranews.com/berita/541901/ahy-resmikan-pembangunan-stasiun-bekasi-ekstensi-berbasis-transit"}]}]$body$::jsonb,
  '/images/berita/stasiun-bekasi-ekstensi.webp',
  $a$Foto ilustrasi penumpang KRL di peron stasiun$a$,
  'terbit',
  '2026-11-20T05:00:00Z'
) on conflict do nothing;

insert into public.posts (id, slug, title, excerpt, body, cover_path, cover_alt, content_status, published_at)
values (
  '5a7e0000-0000-4000-8000-000000000607',
  'rincian-biaya-membeli-rumah-selain-harga-unit',
  $t$Rincian biaya membeli rumah selain harga unit$t$,
  $e$BPHTB, akta jual beli, balik nama, sampai biaya KPR. Daftar ini membantu Anda menyiapkan dana dengan tepat sebelum akad.$e$,
  $body$[{"type": "paragraph", "text": "Harga rumah bukan satu-satunya dana yang perlu disiapkan. Ada pajak, biaya akta, dan biaya bank yang muncul saat transaksi. Mengetahui daftarnya sejak awal membuat perhitungan uang muka lebih akurat."}, {"type": "heading", "text": "1. Pajak dari sisi pembeli"}, {"type": "list", "items": ["BPHTB (Bea Perolehan Hak atas Tanah dan Bangunan): tarifnya paling tinggi 5 persen sesuai UU Nomor 1 Tahun 2022. Dasar hitungnya nilai transaksi dikurangi nilai tidak kena pajak (NPOPTKP) yang ditetapkan pemerintah daerah.", "PPN 11 persen untuk rumah baru dari pengembang. Sepanjang 2026 bisa ditanggung pemerintah kalau memenuhi syarat PMK 90/2025."]}, {"type": "heading", "text": "2. Biaya akta dan sertifikat"}, {"type": "list", "items": ["Akta jual beli (AJB) dibuat di hadapan PPAT. Honor PPAT paling tinggi 1 persen dari nilai transaksi sesuai PP Nomor 24 Tahun 2016.", "Balik nama sertifikat di BPN, termasuk pengecekan sertifikat dan penerbitan atas nama pembeli.", "Pemecahan sertifikat induk kalau rumah dibeli dari perumahan baru, biasanya diurus pengembang."]}, {"type": "heading", "text": "3. Biaya kalau memakai KPR"}, {"type": "list", "items": ["Provisi dan administrasi bank.", "Biaya penilaian (appraisal) rumah oleh bank.", "Asuransi jiwa dan asuransi kebakaran selama tenor.", "Biaya notaris untuk akta perjanjian kredit dan pengikatan hak tanggungan."]}, {"type": "heading", "text": "Tanyakan ini ke pengembang"}, {"type": "paragraph", "text": "Setiap pengembang punya kebijakan berbeda soal biaya yang sudah termasuk harga. Minta rincian tertulis: mana yang ditanggung pengembang, mana yang dibayar pembeli. Di Sejahtera Green Village, rincian biaya yang termasuk dan tidak termasuk harga tercantum di halaman tipe unit."}, {"type": "paragraph", "text": "Setelah daftar biaya lengkap, masukkan angkanya ke Simulasi KPR untuk melihat total dana awal dan cicilan bulanan sekaligus."}]$body$::jsonb,
  '/images/berita/biaya-membeli-rumah.webp',
  $a$Foto ilustrasi penandatanganan dokumen di meja kantor$a$,
  'terbit',
  '2026-11-20T04:00:00Z'
) on conflict do nothing;

insert into public.posts (id, slug, title, excerpt, body, cover_path, cover_alt, content_status, published_at)
values (
  '5a7e0000-0000-4000-8000-000000000608',
  'kpr-syariah-atau-konvensional-mana-yang-cocok',
  $t$KPR syariah atau konvensional: bedanya dan cara memilih$t$,
  $e$Angsuran tetap atau bunga yang bisa berubah. Kenali akad murabahah, MMQ, dan skema bunga KPR konvensional sebelum mengajukan.$e$,
  $body$[{"type": "paragraph", "text": "Pilihan pembiayaan rumah di Indonesia makin lengkap. Sejak 22 Desember 2025, Bank Syariah Nasional (BSN) resmi beroperasi setelah dipisahkan dari BTN, menambah pilihan bank untuk KPR syariah. Sebelum memilih, pahami dulu cara kerja tiap skema."}, {"type": "heading", "text": "KPR konvensional"}, {"type": "paragraph", "text": "Bank memberi pinjaman dan Anda membayar pokok ditambah bunga. Umumnya ada masa bunga tetap (fixed) di awal, lalu bunga mengambang (floating) yang mengikuti kondisi pasar setelahnya."}, {"type": "list", "items": ["Kelebihan: banyak pilihan promo dan tenor, proses yang sudah sangat umum.", "Perlu diperhatikan: cicilan bisa naik saat masa fixed selesai."]}, {"type": "heading", "text": "KPR syariah"}, {"type": "paragraph", "text": "KPR syariah memakai akad yang disepakati di awal. Dua akad yang paling sering dipakai:"}, {"type": "list", "items": ["Murabahah: bank membeli rumah, lalu menjualnya kepada Anda dengan margin yang disepakati. Angsuran tetap dari awal sampai lunas.", "Musyarakah mutanaqisah (MMQ): bank dan Anda memiliki rumah bersama. Porsi Anda bertambah setiap angsuran, dan biaya sewa atas porsi bank bisa ditinjau berkala sesuai akad."]}, {"type": "heading", "text": "Cara memilih"}, {"type": "list", "items": ["Kalau ingin kepastian cicilan sampai lunas, murabahah memberi angka yang tidak berubah.", "Kalau ingin cicilan awal lebih ringan dan siap dengan penyesuaian, skema fixed lalu floating bisa dipertimbangkan.", "Bandingkan total pembayaran sampai lunas, bukan hanya cicilan bulan pertama.", "Tanyakan aturan pelunasan dipercepat dan biayanya di setiap bank."]}, {"type": "paragraph", "text": "Simulasi KPR di website ini menyediakan produk konvensional dan syariah dari bank rekanan, lengkap dengan jadwal angsuran. Bandingkan keduanya untuk harga rumah yang sama."}, {"type": "sources", "items": [{"label": "Bisnis.com, 22 Desember 2025: Bank Syariah Nasional resmi beroperasi usai pisah dari BBTN", "url": "https://finansial.bisnis.com/read/20251222/231/1938770/bank-syariah-nasional-bsn-resmi-beroperasi-usai-pisah-dari-bbtn"}]}]$body$::jsonb,
  '/images/berita/kpr-syariah-konvensional.webp',
  $a$Foto ilustrasi dua orang berjabat tangan di atas dokumen perjanjian$a$,
  'terbit',
  '2026-11-20T03:00:00Z'
) on conflict do nothing;

insert into public.posts (id, slug, title, excerpt, body, cover_path, cover_alt, content_status, published_at)
values (
  '5a7e0000-0000-4000-8000-000000000609',
  'daftar-cek-saat-survei-rumah',
  $t$12 hal yang perlu dicek saat survei rumah$t$,
  $e$Dari legalitas sampai arah matahari. Bawa daftar ini saat survei supaya tidak ada yang terlewat sebelum booking.$e$,
  $body$[{"type": "paragraph", "text": "Survei lokasi adalah kesempatan terbaik untuk memastikan rumah sesuai kebutuhan. Datang dengan daftar pertanyaan membuat waktu survei lebih efektif dan keputusan lebih yakin."}, {"type": "heading", "text": "Legalitas dan transaksi"}, {"type": "list", "items": ["Status sertifikat tanah: SHM atau SHGB, dan apakah sudah dipecah per unit.", "Persetujuan bangunan gedung (PBG) dari pemerintah daerah.", "Skema pembayaran, jadwal serah terima, dan apa yang terjadi kalau serah terima mundur.", "Rincian biaya yang sudah termasuk harga dan yang dibayar terpisah."]}, {"type": "heading", "text": "Lingkungan dan akses"}, {"type": "list", "items": ["Lebar jalan lingkungan dan akses ke jalan utama.", "Saluran air dan kondisi lingkungan saat hujan. Tanyakan juga kepada warga sekitar.", "Jarak ke stasiun, gerbang tol, sekolah, pasar, dan fasilitas kesehatan.", "Keamanan lingkungan dan iuran pengelolaan bulanan."]}, {"type": "heading", "text": "Bangunan"}, {"type": "list", "items": ["Sumber air bersih dan daya listrik terpasang.", "Arah hadap rumah dan sirkulasi udara di setiap ruangan.", "Kualitas dinding, atap, kusen, dan lantai pada unit contoh atau unit jadi.", "Spesifikasi teknis tertulis, supaya bisa dicocokkan saat serah terima."]}, {"type": "paragraph", "text": "Simpan foto dan catatan dari setiap lokasi yang Anda kunjungi. Saat membandingkan dua atau tiga pilihan, catatan ini jauh lebih bisa diandalkan daripada ingatan."}, {"type": "paragraph", "text": "Ingin survei ke Sejahtera Green Village? Hubungi marketing kami lewat WhatsApp untuk mengatur jadwal."}]$body$::jsonb,
  '/images/berita/daftar-cek-survei-rumah.webp',
  $a$Foto ilustrasi tangan mencentang daftar periksa di tablet$a$,
  'terbit',
  '2026-11-20T02:00:00Z'
) on conflict do nothing;

insert into public.posts (id, slug, title, excerpt, body, cover_path, cover_alt, content_status, published_at)
values (
  '5a7e0000-0000-4000-8000-000000000610',
  'mengenal-tambun-selatan-akses-kereta-dan-tol',
  $t$Mengenal Tambun Selatan: akses kereta, tol, dan kawasan sekitarnya$t$,
  $e$Tambun Selatan di Kabupaten Bekasi dilalui KRL lintas Bekasi dan Cikarang serta dekat dengan Tol Jakarta-Cikampek.$e$,
  $body$[{"type": "paragraph", "text": "Tambun Selatan adalah kecamatan di Kabupaten Bekasi, Jawa Barat, di sisi timur Kota Bekasi. Kawasan ini berkembang sebagai area hunian bagi pekerja yang beraktivitas di Jakarta, Kota Bekasi, maupun kawasan industri di Cikarang."}, {"type": "heading", "text": "Akses kereta"}, {"type": "paragraph", "text": "Stasiun Tambun berada di jalur KRL Commuter Line lintas Bekasi dan Cikarang. Dari sini penumpang bisa menuju Jakarta tanpa harus menyetir, lalu melanjutkan perjalanan dengan moda lain di stasiun transit."}, {"type": "paragraph", "text": "Di Kota Bekasi, pembangunan Stasiun Bekasi Ekstensi yang dimulai Juli 2026 akan menambah titik perpindahan ke bus dan LRT Jabodebek setelah selesai."}, {"type": "heading", "text": "Akses jalan tol"}, {"type": "paragraph", "text": "Pengguna kendaraan pribadi bisa masuk Tol Jakarta-Cikampek lewat Gerbang Tol Bekasi Timur. Dari tol ini, perjalanan bisa diteruskan ke arah Jakarta maupun Cikarang dan Karawang."}, {"type": "heading", "text": "Fasilitas sehari-hari"}, {"type": "list", "items": ["Pusat belanja dan area komersial di sepanjang jalan utama Tambun.", "Kantor cabang bank, termasuk di sekitar Mangunjaya.", "Sekolah, pasar, dan fasilitas kesehatan di tingkat kecamatan."]}, {"type": "heading", "text": "Sejahtera Green Village di Tambun Selatan"}, {"type": "paragraph", "text": "Sejahtera Green Village berada di Mangunjaya, Tambun Selatan. Proyek ini terdiri dari 16 unit rumah tipe 36 dengan luas tanah 60 sampai 73 meter persegi. Lihat detail lokasi, foto, dan tempat penting di sekitarnya di halaman proyek, atau atur jadwal survei bersama marketing kami."}]$body$::jsonb,
  '/images/berita/mengenal-tambun-selatan.webp',
  $a$Foto ilustrasi jalan tol yang melintasi kawasan hijau dilihat dari udara$a$,
  'terbit',
  '2026-11-20T01:00:00Z'
) on conflict do nothing;
